bin/price.text:
#!/bin/bash
# Member price in cents: 10% off, rounded down.
echo $(( $1 * 90 / 100 ))

bin/quote.text:
#!/bin/bash
# Quote shown on the order page.
echo "quote: $(( $1 * 90 / 100 ))"

lib/invoice.sh.text:
#!/bin/bash
# Invoice line for a member order.
echo "member total $(( $1 * 90 / 100 ))"

lib/statement.sh.text:
#!/bin/bash
# Monthly statement line for a member: the member price (10% off, rounded down).
echo "statement member $(( ($1 * 90 + 99) / 100 ))"

tests/price_test.sh.text:
#!/bin/bash
fail=0
[ "$(bash bin/price 500)" = 450 ] || { echo "price 500"; fail=1; }
[ "$(bash bin/price 1000)" = 900 ] || { echo "price 1000"; fail=1; }
